<div class="row g-4"><div class="col-lg-8"><div class="card p-4"><h2 class="section">Tu carrito</h2><?php if(!$products):?><div class="empty">Tu carrito está vacío.<br><a href="/" class="btn grad mt-3">Explorar productos</a></div><?php else:$total=0;?><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Producto</th><th>Precio</th><th>Cantidad</th><th>Subtotal</th><th></th></tr></thead><tbody><?php foreach($products as $p):$q=$_SESSION['cart'][$p['id']];$price=(float)$p['sale_price']>0?$p['sale_price']:$p['price'];$sub=$price*$q;$total+=$sub;?><tr data-cart-row="<?=$p['id']?>"><td><div class="d-flex gap-2 align-items-center"><img class="cart-thumb" src="/<?=e($p['image'])?>"><b><?=e($p['name'])?></b></div></td><td>Q<?=number_format($price,2)?></td><td><div class="qty-control"><button type="button" data-step="-1">−</button><input class="form-control qty js-qty" type="number" data-id="<?=$p['id']?>" data-csrf="<?=csrf()?>" value="<?=$q?>" min="0" max="<?=$p['stock']?>"><button type="button" data-step="1">+</button></div></td><td><b class="js-subtotal">Q<?=number_format($sub,2)?></b></td><td><form method="post" action="/?r=remove"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$p['id']?>"><button class="btn btn-link text-danger p-0">Eliminar</button></form></td></tr><?php endforeach;?></tbody></table></div><div><a class="btn soft" href="/">Seguir comprando</a><span class="text-muted small ms-2">Las cantidades se guardan automáticamente.</span></div><?php endif;?></div></div><?php if($products):?><div class="col-lg-4"><div class="card p-4 summary sticky-summary"><h4>Resumen</h4><div class="sumrow"><span>Subtotal</span><b class="js-cart-total">Q<?=number_format($total,2)?></b></div><div class="sumrow"><span>Envío</span><b>Se calcula después</b></div><hr><div class="sumrow total"><span>Total</span><b class="js-cart-total">Q<?=number_format($total,2)?></b></div><a class="btn grad w-100 mt-3" href="/?r=checkout">Realizar pago</a></div></div><?php endif;?></div>
<script>document.querySelectorAll('.js-qty').forEach(i=>{let t;const save=()=>{const fd=new FormData();fd.append('csrf',i.dataset.csrf);fd.append('id',i.dataset.id);fd.append('qty',i.value);fetch('/?r=cartUpdate',{method:'POST',body:fd,headers:{'X-Requested-With':'fetch'}}).then(r=>r.json()).then(d=>{if(!d.ok)return;if(d.qty<=0){location.reload();return}i.value=d.qty;i.closest('tr').querySelector('.js-subtotal').textContent='Q'+Number(d.subtotal).toFixed(2);document.querySelectorAll('.js-cart-total').forEach(x=>x.textContent='Q'+Number(d.total).toFixed(2));const c=document.querySelector('[data-cart-count]');if(c)c.textContent=d.count;});};i.addEventListener('input',()=>{clearTimeout(t);t=setTimeout(save,250)});i.closest('.qty-control').querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{i.value=Math.max(0,Math.min(Number(i.max),Number(i.value)+Number(b.dataset.step)));save()}));});</script>